#include <DHT.h>
DHT sensor({{P0}}, DHT11);

void setup() {
  Serial.begin(9600);
  sensor.begin();
  delay(2500);
}

void loop() {
  float h = sensor.readHumidity();
  float t = sensor.readTemperature();
  if (isnan(h) || isnan(t)) {
    Serial.println("Check DHT wiring");
  } else {
    Serial.print(t, 1);
    Serial.print(" C, ");
    Serial.print(h, 1);
    Serial.println(" % RH");
  }
  delay(2500);
}

